CREATE TABLE public.career_resumes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, job_id uuid, title text NOT NULL DEFAULT 'Resume review', jd text NOT NULL, original_text text NOT NULL, original_filename text, original_type text, original_path text, consent_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), analysis jsonb, recommendations jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'ready', error text, analysis_lease_until timestamptz, revision integer NOT NULL DEFAULT 0, CHECK (length(original_text) BETWEEN 40 AND 24000), CHECK (length(jd) BETWEEN 80 AND 24000));
GRANT SELECT, DELETE ON public.career_resumes TO authenticated; GRANT ALL ON public.career_resumes TO service_role;
ALTER TABLE public.career_resumes ENABLE ROW LEVEL SECURITY;
CREATE POLICY career_resume_read ON public.career_resumes FOR SELECT TO authenticated USING (user_id=auth.uid() AND expires_at>now());
CREATE POLICY career_resume_delete ON public.career_resumes FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE INDEX career_resume_owner ON public.career_resumes(user_id,expires_at);
CREATE TABLE public.career_resume_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resume_id uuid NOT NULL REFERENCES public.career_resumes(id) ON DELETE CASCADE, version integer NOT NULL, content text NOT NULL, decisions jsonb NOT NULL, template text NOT NULL, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(resume_id,version));
GRANT SELECT ON public.career_resume_versions TO authenticated; GRANT ALL ON public.career_resume_versions TO service_role;
ALTER TABLE public.career_resume_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY career_version_owner ON public.career_resume_versions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.career_resumes r WHERE r.id=resume_id AND r.user_id=auth.uid() AND r.expires_at>now()));
CREATE TABLE public.career_resume_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resume_id uuid NOT NULL REFERENCES public.career_resumes(id) ON DELETE CASCADE, version_id uuid NOT NULL REFERENCES public.career_resume_versions(id) ON DELETE CASCADE, recommendation_id text NOT NULL, decision text NOT NULL CHECK(decision IN ('accepted','rejected','pending')), proposed_text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.career_resume_approvals TO authenticated; GRANT ALL ON public.career_resume_approvals TO service_role;
ALTER TABLE public.career_resume_approvals ENABLE ROW LEVEL SECURITY;
CREATE POLICY career_approval_owner ON public.career_resume_approvals FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.career_resumes r WHERE r.id=resume_id AND r.user_id=auth.uid() AND r.expires_at>now()));
CREATE TABLE public.career_generated_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resume_id uuid NOT NULL REFERENCES public.career_resumes(id) ON DELETE CASCADE, version_id uuid NOT NULL REFERENCES public.career_resume_versions(id) ON DELETE CASCADE, format text NOT NULL CHECK(format IN ('docx','pptx')), bytes integer NOT NULL CHECK(bytes>0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.career_generated_documents TO authenticated; GRANT ALL ON public.career_generated_documents TO service_role;
ALTER TABLE public.career_generated_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY career_generated_owner ON public.career_generated_documents FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.career_resumes r WHERE r.id=resume_id AND r.user_id=auth.uid() AND r.expires_at>now()));
CREATE POLICY career_quarantine_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='career-resume-quarantine' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.career_resumes r WHERE r.id::text=(storage.foldername(name))[2] AND r.user_id=auth.uid() AND r.expires_at>now() AND r.original_path=name));
CREATE POLICY career_quarantine_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='career-resume-quarantine' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.commit_career_analysis(p_id uuid,p_user uuid,p_analysis jsonb,p_recommendations jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.career_resumes SET analysis=p_analysis,recommendations=p_recommendations,status='completed',error=NULL,analysis_lease_until=NULL WHERE id=p_id AND user_id=p_user AND expires_at>now() AND status='processing'; IF NOT FOUND THEN RAISE EXCEPTION 'Resume no longer available for analysis'; END IF; END $$;
REVOKE ALL ON FUNCTION public.commit_career_analysis(uuid,uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.commit_career_analysis(uuid,uuid,jsonb,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.save_career_version(p_id uuid,p_user uuid,p_revision integer,p_content text,p_decisions jsonb,p_template text,p_approve boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid; d jsonb; BEGIN PERFORM 1 FROM public.career_resumes WHERE id=p_id AND user_id=p_user AND expires_at>now() AND revision=p_revision FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Resume changed; reload before saving'; END IF; INSERT INTO public.career_resume_versions(resume_id,version,content,decisions,template,approved_at) VALUES(p_id,p_revision+1,p_content,p_decisions,p_template,CASE WHEN p_approve THEN now() ELSE NULL END) RETURNING id INTO v; FOR d IN SELECT value FROM jsonb_array_elements(p_decisions) LOOP INSERT INTO public.career_resume_approvals(resume_id,version_id,recommendation_id,decision,proposed_text) VALUES(p_id,v,d->>'id',d->>'status',d->>'replacement'); END LOOP; UPDATE public.career_resumes SET revision=p_revision+1 WHERE id=p_id; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.save_career_version(uuid,uuid,integer,text,jsonb,text,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_career_version(uuid,uuid,integer,text,jsonb,text,boolean) TO service_role;